                        oVideoDetails.sVideoName = Convert.ToString(oSqlDataReader["VideoName"]);
                        oVideoDetails.MoreVideo = Convert.ToInt32(oSqlDataReader["Count"]);
                        oVideoDetails.StartDate = Convert.ToDateTime(oSqlDataReader["StartDate"]);
                        oVideoDetails.EndDate = Convert.ToDateTime(oSqlDataReader["EndDate"]);
