                        oVideoDetails.UserRoleIds = Convert.ToString(oSqlDataReader["UserRoleIds"]);
                        oVideoDetails.StandardDivisionIds = Convert.ToString(oSqlDataReader["StandardDivIds"]);
                        oVideoDetails.ShowOnExternalWebsite = Convert.ToBoolean(oSqlDataReader["ShowOnExternalWebsite"]);
                    }
                    return oVideoDetails;
